    number_format_notation='f', apply_hash=True, ignore_type_in_groups=None,
    ignore_string_type_changes=False, ignore_numeric_type_changes=False,
    ignore_type_subclasses=False, ignore_string_case=False, use_enum_value=
    False, exclude_obj_callback=None, number_to_string_func=None,
    ignore_private_variables=True, parent='root', encodings=None,
    ignore_encoding_errors=False, ignore_iterable_order=True, **kwargs):
    if kwargs:
        raise ValueError(
            ("The following parameter(s) are not valid: %s\n"
             "The valid parameters are obj, hashes, exclude_types, significant_digits, truncate_datetime,"
